            supp_mols.add(r['qname'])
            supp_reads.append(supp_info)

    return {
        'depth': len(depth_mols),
        'alt': len(supp_mols),
        'supp_mols': supp_mols,
        'supp_reads': supp_reads,
        'fwd_cov': fwd_cov,
        'rev_cov': rev_cov
    }

results = []
for c in candidates:
    t_res = analyze_sample(tumor_reads, c)
    n_res = analyze_sample(normal_reads, c)

    t_alt = t_res['alt']
    t_depth = t_res['depth']
    t_vaf = t_alt / t_depth if t_depth > 0 else 0.0

    n_alt = n_res['alt']
    n_depth = n_res['depth']
    n_vaf = n_alt / n_depth if n_depth > 0 else 0.0

    tag = None
    if n_alt >= 2 and n_depth > 0 and (n_alt / n_depth) >= 0.05:
        tag = 'GERMLINE'
    elif t_alt < 4:
        tag = 'LOW_SUPPORT'
    else:
        low_bq = sum(1 for s in t_res['supp_reads'] if s['bq'] < 20)
        if low_bq >= 0.75 * t_alt:
            tag = 'LOW_BASE_QUALITY'
        else:
            low_mapq = sum(1 for s in t_res['supp_reads'] if s['mapq'] < 20)
            if low_mapq >= 0.75 * t_alt:
                tag = 'LOW_MAPPING_QUALITY'
            else:
                avg_mis = sum(s['mismatches'] for s in t_res['supp_reads']) / t_alt
                if avg_mis >= 4.0:
                    tag = 'MULTI_MISMATCH'
                else:
                    fwd_supp = sum(1 for s in t_res['supp_reads'] if not s['is_rev'])
                    rev_supp = sum(1 for s in t_res['supp_reads'] if s['is_rev'])
                    if t_res['fwd_cov'] > 0 and t_res['rev_cov'] > 0:
                        if max(fwd_supp, rev_supp) / t_alt >= 0.90:
                            tag = 'STRAND_BIAS'
                    if tag is None:
                        read_end = sum(1 for s in t_res['supp_reads'] if s['dist_end'] < 5)
                        if read_end >= 0.75 * t_alt:
                            tag = 'READ_END'
                        else:
                            disc = sum(1 for s in t_res['supp_reads'] if s['tlen'] > 1000)
                            if disc >= 0.75 * t_alt:
                                tag = 'DISCORDANT_PAIRS'

    results.append({
        'cand': c,
        't_alt': t_alt,
        't_depth': t_depth,
        't_vaf': t_vaf,
        'n_alt': n_alt,
        'n_depth': n_depth,
        't_res': t_res,
        'tag': tag
    })

for i in range(len(results) - 1):
    r1 = results[i]
    r2 = results[i + 1]
    c1 = r1['cand']
    c2 = r2['cand']
    is_snv1 = (len(c1['ref']) == 1 and len(c1['alt']) == 1)
    is_snv2 = (len(c2['ref']) == 1 and len(c2['alt']) == 1)
    if is_snv1 and is_snv2 and c2['pos'] == c1['pos'] + 1:
        if r1['tag'] is None and r2['tag'] is None:
            m1 = r1['t_res']['supp_mols']
            m2 = r2['t_res']['supp_mols']
            shared = m1 & m2
            either = m1 | m2
            frac = len(shared) / len(either) if len(either) > 0 else 0
            print(f'Adjacent: {c1["id"]} and {c2["id"]}: shared={len(shared)}, either={len(either)}, frac={frac:.3f}')
            if frac >= 0.90:
                r2['tag'] = 'MNV_PARTNER'

for r in results:
    if r['tag'] is None:
        r['tag'] = 'PASS'
        r['call'] = 'somatic'
    else:
        r['call'] = 'fail'
    c = r['cand']
    print(f"{c['id']}\t{c['pos']}\t{c['ref']}->{c['alt']}\tcall={r['call']}\ttag={r['tag']}\tt_alt={r['t_alt']}\tt_dp={r['t_depth']}\tn_alt={r['n_alt']}\tn_dp={r['n_depth']}")
